import { it, expect, vi, beforeEach, afterEach } from 'vitest';
import { webcrypto, createHash } from 'node:crypto';
import { render, screen, fireEvent, cleanup, act } from '@testing-library/react';
vi.mock('next-auth/react',()=>({useSession:()=>({data:null,status:'unauthenticated'})}));
import { IntentSpecConfirmation } from '../../../EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web/src/components/IntentSpecConfirmation';
import { createIntentSpecReview, updateReviewDecision, acknowledgeIntentSpecReview } from '../../../EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web/src/lib/intent-spec-review';
const sheetButton='Download technical review worksheet (unfinished)';
beforeEach(()=>vi.stubGlobal('crypto',webcrypto));
afterEach(()=>{cleanup();vi.restoreAllMocks();vi.unstubAllGlobals();});
function state(){let s=createIntentSpecReview({problem:'Independent current source'},'  \r\nIndependently bound source\n```\n  ');for(const d of s.decisions)s=updateReviewDecision(s,d.id,{answer:'Local answer '+d.id});return acknowledgeIntentSpecReview(s);}
function open(){fireEvent.click(screen.getByRole('button',{name:'Keep a review copy for comparison'}));fireEvent.change(screen.getByLabelText('Reviewer name (self-declared)'),{target:{value:'Local A'}});}
async function create(){fireEvent.click(screen.getByRole('button',{name:'Create file for reviewed revision'}));await screen.findByRole('button',{name:sheetButton});}
async function text(blob:Blob){return new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result as string);r.onerror=reject;r.readAsText(blob);});}
function downloads(){const blobs:Blob[]=[];vi.spyOn(URL,'createObjectURL').mockImplementation(b=>{blobs.push(b as Blob);return 'blob:local';});const cleanup=vi.spyOn(URL,'revokeObjectURL').mockImplementation(()=>{});vi.spyOn(HTMLAnchorElement.prototype,'click').mockImplementation(()=>{});return {blobs,cleanup};}
it('independently pairs downloaded exact JSON with worksheet and invalidates language and acknowledgement',async()=>{
 const s=state();const view=render(<IntentSpecConfirmation review={s} language="en"/>);open();await create();const d=downloads();
 fireEvent.click(screen.getByRole('button',{name:'Download review file'}));fireEvent.click(screen.getByRole('button',{name:sheetButton}));
 const json=await text(d.blobs[0]);const sheet=await text(d.blobs[1]);const draft=JSON.parse(json).payload.draft;
 expect(sheet).toContain(createHash('sha256').update(json).digest('hex'));expect(sheet).toContain(draft);expect(d.cleanup).toHaveBeenCalledTimes(2);
 view.rerender(<IntentSpecConfirmation review={s} language="vi"/>);expect(screen.queryByRole('button',{name:sheetButton})).toBeNull();expect(screen.queryByRole('button',{name:'Tải phiếu review kỹ thuật (chưa hoàn thành)'})).toBeNull();
 view.rerender(<IntentSpecConfirmation review={{...s,acknowledgedRevision:null}} language="en"/>);expect(screen.queryByRole('button',{name:sheetButton})).toBeNull();expect((screen.getByRole('button',{name:'Create file for reviewed revision'}) as HTMLButtonElement).disabled).toBe(true);
});
