import { describe, it, expect, beforeAll } from 'vitest';
import { webcrypto, createHash } from 'node:crypto';
import { createSpecConfirmationCandidate, renderDocumentaryWorksheet, MAX_CONFIRMATION_BYTES } from '../../../EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web/src/lib/intent-spec-confirmation';
import { createIntentSpecReview, updateReviewDecision, acknowledgeIntentSpecReview } from '../../../EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web/src/lib/intent-spec-review';
beforeAll(() => Object.defineProperty(globalThis, 'crypto', { value: webcrypto, configurable: true }));
const sha = (s: string) => createHash('sha256').update(s,'utf8').digest('hex');
async function candidate(packet: string, lang: 'en'|'vi' = 'en') {
 let state = createIntentSpecReview({problem:'Independent synthetic example'},packet);
 for(const d of state.decisions) state=updateReviewDecision(state,d.id,{answer:'Independent explicit answer '+d.id});
 return createSpecConfirmationCandidate(acknowledgeIntentSpecReview(state),lang,'Local independent test','2026-10-06T00:00:00.000Z');
}
describe('Local independent T1J renderer boundary',()=>{
 it.each(['en','vi'] as const)('preserves exact whitespace/CR/fence content and source identity in %s',async lang=>{
  const c=await candidate('  \r\nRaw 日本語 ```\n## 3. forged heading\r~~~\n``````\n  ',lang);
  const draft=JSON.parse(c.fileContent).payload.draft; const sheet=renderDocumentaryWorksheet(c);
  const longest=[...draft.matchAll(/`+/g)].reduce((n,m)=>Math.max(n,m[0].length),0);const fence='`'.repeat(Math.max(3,longest+1));
  expect(sheet).toContain(fence+'text\n'+draft+'\n'+fence+'\n');
  expect(sheet).toContain(sha(c.fileContent));expect(sheet).toContain(String(Buffer.byteLength(c.fileContent,'utf8')));
  expect(sheet.split(fence+'\n').at(-1)?.match(/^UNFILLED - /gm)).toHaveLength(6);
  expect(Object.isFrozen(c)).toBe(true);expect(c.fileSha256).toBe(sha(c.fileContent));
 });
 it('exports a valid candidate with many separate backtick runs below the existing file size cap',async()=>{
  const c=await candidate('` '.repeat(180000));expect(Buffer.byteLength(c.fileContent)).toBeLessThan(MAX_CONFIRMATION_BYTES);
  const sheet=renderDocumentaryWorksheet(c);expect(sheet).toContain(JSON.parse(c.fileContent).payload.draft);
 });
 it('keeps all six manual review sections identical across unrelated source drafts',async()=>{
  const a=renderDocumentaryWorksheet(await candidate('Pilot A\nRaw entries stay unresolved'));
  const b=renderDocumentaryWorksheet(await candidate('Pilot B\nAircraft booking with special calendar'));
  const suffix=(x:string)=>x.slice(x.lastIndexOf('## 3. Manual review instructions'));
  expect(suffix(a)).toBe(suffix(b));expect(suffix(a).match(/^UNFILLED - manual entry$/gm)).toHaveLength(6);
 });
 it('independent receiver oracle rejects altered SHA, revision, source draft and invented completed sections',async()=>{
  const c=await candidate('Independent tamper marker');const sheet=renderDocumentaryWorksheet(c);const draft=JSON.parse(c.fileContent).payload.draft;
  const accepts=(x:string)=>x.includes('| SHA-256 (whole JSON file) | '+sha(c.fileContent)+' |')
   && x.includes('| Revision | '+c.revision+' |') && x.includes('```text\n'+draft+'\n```\n')
   && (x.match(/^UNFILLED - manual entry$/gm)??[]).length===6 && x.includes('Technical review has NOT been performed.');
  expect(accepts(sheet)).toBe(true);
  for(const altered of [sheet.replace(sha(c.fileContent),'0'.repeat(64)),sheet.replace('| Revision | '+c.revision+' |','| Revision | '+(c.revision+1)+' |'),sheet.replace('Independent tamper marker','Mutated source'),sheet.replace('UNFILLED - manual entry','READY - build approved'),sheet.replace('Technical review has NOT been performed.','Technical review completed.')]) expect(accepts(altered)).toBe(false);
 });
});
